// Read the Telegram update (a message, or a tap on a button) and decide what kind it is.
const update = $input.first().json;

// --- Button taps ---
const cb = update.callback_query;
if (cb) {
  const data = String(cb.data || '');
  const base = {
    chat_id: cb.message && cb.message.chat && cb.message.chat.id,
    text: '', added_by: (cb.from && cb.from.first_name) || 'unknown', source: 'text',
    help_text: '👍 OK, nothing was deleted.',
    delete_id: null, delete_query: '', file_id: null, file_mime: null, file_kind: null,
    rem_hour: null, rem_plan: null,
    is_button: true, callback_id: cb.id,
  };
  let m;
  if ((m = data.match(/^del:(\d+)$/))) return [{ json: { ...base, type: 'delete', delete_id: parseInt(m[1], 10) } }];
  if (data === 'rmenu:time') return [{ json: { ...base, type: 'rem_pick_time' } }];
  if (data === 'rmenu:plan') return [{ json: { ...base, type: 'rem_pick_plan' } }];
  if ((m = data.match(/^rset:hour:(\d{1,2})$/)) && +m[1] < 24) return [{ json: { ...base, type: 'rem_set', rem_hour: +m[1] } }];
  if ((m = data.match(/^rset:plan:([a-z]+)$/))) return [{ json: { ...base, type: 'rem_set', rem_plan: m[1] } }];
  return [{ json: { ...base, type: 'cancel' } }];
}

const msg = update.message || {};
const text = String(msg.text || msg.caption || '').trim();
const from = msg.from || {};
const addedBy = [from.first_name, from.last_name].filter(Boolean).join(' ') || from.username || 'unknown';

const usage =
  "👋 I'm the Deadline Bot.\n\n" +
  "• Send me a deadline in plain words, e.g. \"Data Viz report due 24/10 at 23:59\"\n" +
  "• Or send a photo or PDF (syllabus, slide, screenshot) – I'll read the dates\n" +
  "• /deadlines – see everything coming up\n" +
  "• /reminders – choose when and how often I remind you\n" +
  "• To delete one, just write e.g. \"delete the Data Viz report\"\n" +
  "• /help – show this message";

function dist(a, b) {
  const m = Array.from({ length: a.length + 1 }, (_, i) => [i, ...Array(b.length).fill(0)]);
  for (let j = 1; j <= b.length; j++) m[0][j] = j;
  for (let i = 1; i <= a.length; i++)
    for (let j = 1; j <= b.length; j++)
      m[i][j] = Math.min(m[i-1][j] + 1, m[i][j-1] + 1, m[i-1][j-1] + (a[i-1] === b[j-1] ? 0 : 1));
  return m[a.length][b.length];
}

const MAX_MB = 15;
let type;
let helpText = usage;
let deleteId = null;
let deleteQuery = '';
let fileId = null, fileMime = null, fileKind = null;
let remHour = null, remPlan = null;

const doc = msg.document;
const docMime = (doc && doc.mime_type) || '';
const docReadable = doc && (docMime.startsWith('image/') || docMime === 'application/pdf');

if (msg.photo && msg.photo.length) {
  type = 'file';
  fileId = msg.photo[msg.photo.length - 1].file_id;
  fileMime = 'image/jpeg';
  fileKind = 'photo';
} else if (docReadable) {
  if ((doc.file_size || 0) > MAX_MB * 1024 * 1024) {
    type = 'unsupported';
    helpText = `📎 That file is too big – I can read files up to ${MAX_MB} MB.`;
  } else {
    type = 'file';
    fileId = doc.file_id;
    fileMime = docMime;
    fileKind = docMime === 'application/pdf' ? 'pdf' : 'photo';
  }
} else if (msg.voice || msg.audio || msg.video || msg.video_note || msg.sticker || doc) {
  type = 'unsupported';
  helpText = "📎 I can read typed text, photos and PDFs – not this kind of file yet.\n\n" + usage;
} else if (text.startsWith('/')) {
  const cmd = text.split(/[\s@]/)[0].toLowerCase();
  const quick = cmd.match(/^\/delete_(\d+)$/);
  if (cmd === '/deadlines') type = 'deadlines';
  else if (cmd === '/reminders' || cmd === '/reminder' || cmd === '/remind') type = 'reminders';
  else if (quick) { type = 'delete'; deleteId = parseInt(quick[1], 10); }
  else if (cmd === '/delete') {
    const n = parseInt(text.split(/\s+/)[1], 10);
    if (Number.isInteger(n) && n > 0) { type = 'delete'; deleteId = n; }
    else {
      type = 'delete_help';
      helpText = "🗑️ To delete a deadline, just write e.g. \"delete the Data Viz report\".";
    }
  }
  else if (cmd === '/start' || cmd === '/help') {
    // Links from the website carry reminder settings, e.g. "/start r_18_planner"
    const payload = (text.split(/\s+/)[1] || '').toLowerCase();
    const rm = payload.match(/^r_(\d{1,2})_(chill|normal|planner|early|intense|countdown)$/);
    if (cmd === '/start' && rm && +rm[1] < 24) { type = 'rem_set'; remHour = +rm[1]; remPlan = rm[2]; }
    else if (cmd === '/start' && payload === 'reminders') type = 'reminders';
    else type = 'help';
  }
  else {
    type = 'unknown_command';
    const guess = ['/deadlines', '/reminders', '/delete', '/help'].find(c => dist(cmd, c) <= 3);
    helpText = (guess ? `🤔 I don't know ${cmd}. Did you mean ${guess}?\n\n` : `🤔 I don't know ${cmd}.\n\n`) + usage;
  }
} else if (text && /\b(delete|remove|erase|cancel)\b/i.test(text)) {
  type = 'delete_text';
  deleteQuery = text;
} else if (text) {
  type = 'text';
} else {
  type = 'unsupported';
}

return [{
  json: {
    type, chat_id: msg.chat?.id, text, added_by: addedBy, source: 'text', help_text: helpText,
    delete_id: deleteId, delete_query: deleteQuery, file_id: fileId, file_mime: fileMime, file_kind: fileKind,
    rem_hour: remHour, rem_plan: remPlan, is_button: false, callback_id: null,
  },
}];

// Format upcoming deadlines as a readable list, soonest first.
const rows = $input.all().map(i => i.json).filter(r => r && r.id);

if (rows.length === 0) {
  return [{ json: { reply: '🎉 No upcoming deadlines saved yet.\nSend me one, e.g. "Data Viz report due 24/10 at 23:59"' } }];
}

rows.sort((a, b) => new Date(a.due_at) - new Date(b.due_at));
const today = $now.setZone('Europe/Paris').startOf('day');

const lines = rows.map(r => {
  const dt = DateTime.fromISO(r.due_at, { zone: 'Europe/Paris' }).setLocale('en');
  const days = Math.round(dt.startOf('day').diff(today, 'days').days);
  const when = days === 0 ? 'today' : days === 1 ? 'tomorrow' : `in ${days} days`;
  const flag = r.conflict ? ' ⚠️ conflicting date' : '';
  return `• ${dt.toFormat('ccc d LLL, HH:mm')} (${when})${flag}\n   ${r.course} – ${r.title}`;
});

return [{ json: { reply: `📅 Upcoming deadlines (${rows.length}):\n\n` + lines.join('\n') +
  '\n\n🗑️ To delete one, just write e.g. "delete the ' + rows[0].course + ' ' + rows[0].title + '"' } }];

// Confirm what was deleted.
const r = $('Supabase: find deadline').first().json;
const dt = DateTime.fromISO(r.due_at, { zone: 'Europe/Paris' }).setLocale('en').toFormat('ccc d LLL, HH:mm');
return [{ json: { reply: `🗑️ Deleted: ${r.course} – ${r.title} (${dt})\n\nSend /deadlines to see the updated list.` } }];

// Send the downloaded file to the sub-workflow together with the message details
// (caption, who sent it, photo or PDF). The sub-workflow reads the file with Claude.
const p = $('Prepare message').first().json;
return [{ json: { ...p, source: p.file_kind }, binary: $input.first().binary }];

// Find which saved deadline the student wants to delete (word matching, no AI needed).
const q = $('Prepare message').first().json.delete_query;
const rows = $input.all().map(i => i.json).filter(r => r && r.id);

const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
const STOP = new Set(('the a an my our your for of to on in at by and or is it its that this these please deadline deadlines ' +
  'delete remove erase cancel not anymore due date from can could you i we want would like me thanks thank pls ' +
  'jan january feb february mar march apr april may jun june jul july aug august sep sept september oct october ' +
  'nov november dec december monday tuesday wednesday thursday friday saturday sunday today tomorrow next').split(' '));
const words = s => norm(s).split(' ').filter(w => w && !STOP.has(w) && !/^\d+(st|nd|rd|th)?$/.test(w));
const fmt = iso => DateTime.fromISO(iso, { zone: 'Europe/Paris' }).setLocale('en').toFormat('ccc d LLL, HH:mm');

const qw = words(q);
if (!qw.length) {
  return [{ json: { has_match: false, reply: "🗑️ Which deadline should I delete? Write e.g. \"delete the Data Viz report\"." } }];
}

const scored = rows.map(r => {
  const rw = words(`${r.course} ${r.title}`);
  const initials = norm(r.course).split(' ').filter(Boolean).map(w => w[0]).join('');   // "machine learning" -> "ml"
  const hit = w => {
    if (rw.some(x => x === w || (Math.min(x.length, w.length) >= 3 && (x.startsWith(w) || w.startsWith(x))))) return 1;
    return w === initials ? 0.9 : 0;     // abbreviation counts a bit less than the full word
  };
  return { r, score: qw.reduce((s, w) => s + hit(w), 0) / qw.length };
}).filter(s => s.score >= 0.5)
  .sort((a, b) => b.score - a.score || new Date(a.r.due_at) - new Date(b.r.due_at));

if (scored.length === 0) {
  return [{ json: { has_match: false, reply: `🤔 I couldn't find a saved deadline matching "${q}".\nSend /deadlines to see the list.` } }];
}

const best = scored[0].r;
const others = scored.filter(s => s.score === scored[0].score).length - 1;
const note = others > 0 ? `\n\n(${others} other deadline${others > 1 ? 's match' : ' matches'} too – this is the soonest. Ask again after to delete the next.)` : '';
return [{ json: {
  has_match: true,
  delete_id: best.id,
  reply: `🗑️ Delete this deadline?\n\n${best.course} – ${best.title}\n${fmt(best.due_at)}${note}`,
} }];

